class InstalledPackagesPage extends StatefulWidget{const InstalledPackagesPage({super.key});@override State<InstalledPackagesPage>createState()=>_S();}class _S extends State<InstalledPackagesPage>{dynamic pip,npm;bool loading=true;@override void initState(){super.initState();load();}Future<void>load()async{final r=await Future.wait([DioClient.instance.dio.get(ApiEndpoints.depsPip),DioClient.instance.dio.get(ApiEndpoints.depsNpm)]);if(mounted)setState((){pip=r[0].data;npm=r[1].data;loading=false;});}@override Widget build(BuildContext c){final p=pip is List?pip as List:[];final deps=npm is Map&&npm['dependencies']is Map?npm['dependencies']as Map:{};return Scaffold(backgroundColor:Colors.transparent,appBar:AppBar(title:const Text('系统依赖清单')),body:loading?const Center(child:CircularProgressIndicator()):ListView(padding:const EdgeInsets.all(20),children:[const Text('Python',style:TextStyle(fontWeight:FontWeight.bold)),...p.whereType<Map>().map((x)=>AppCard(margin:const EdgeInsets.only(bottom:6),child:Text('${x['name']} ${x['version']}'))),const Text('Node.js',style:TextStyle(fontWeight:FontWeight.bold)),...deps.entries.map((x)=>AppCard(margin:const EdgeInsets.only(bottom:6),child:Text('${x.key} ${(x.value as Map)['version']}'))]));}}
